# =========================================================================================
# Parser from Markdown_Translate.py (Token Manipulation)
# =========================================================================================

class MarkdownTranslationLogic:
    """
    负责 Markdown 结构解析和文本提取的核心逻辑
    优化：基于 Token 的结构保护模式。
    策略：
    1. 使用 markdown-it 解析 Markdown 为 Tokens (AST)。
    2. 遍历 Tokens，识别可翻译的文本节点 (Text Node)。
    3. 这里的“可翻译”是指 Paragraph, Heading, List Item, Blockquote 等容器内的 inline 文本。
    4. 提取需翻译文本，进行批量/逐个翻译。
    5. 更新 Token 的 content。
    6. 使用 SimpleMarkdownRenderer 将 Token 树还原为 Markdown 字符串。
    """
    
    def __init__(self):
        # 启用 table 支持以正确识别表格结构
        # 启用 html 以识别 xml/html tags
        self.md_parser = MarkdownIt("gfm-like").enable(['table', 'linkify', 'strikethrough'])
        self.renderer = SimpleMarkdownRenderer()

    def _extract_translatable_content(self, tokens):
        """
        从Markdown tokens中提取可翻译的文本内容 (引用自 AI_Markdown_Translater.py)
        """
        texts_to_translate = []
        nodes_to_update = []
        
        # 定义包含可翻译文本的容器类型 (移除了 th_open, td_open 以停止翻译表格)
        TRANSLATABLE_CONTAINERS = {"paragraph_open", "heading_open", "list_item_open", "blockquote_open"}
        
        # 遍历 tokens
        i = 0
        while i < len(tokens):
            token = tokens[i]
            
            # 查找容器开始
            if token.type in TRANSLATABLE_CONTAINERS:
                if (i + 1) < len(tokens) and tokens[i+1].type == 'inline':
                    inline_token = tokens[i+1]
                    if inline_token.children:
                        for child_node in inline_token.children:
                            if child_node.type == 'text' and child_node.content.strip():
                                content = child_node.content
                                if not re.match(r'^[ \t\n!@#$%^&*()_\-+={}\[\]|\\:;"\'<>,.?/~`]+$', content):
                                    # 排除已是占位符的内容 (不重复翻译)
                                    if not re.match(r'^MATH_FIXED_\d+X$', content.strip()):
                                        texts_to_translate.append(content)
                                        nodes_to_update.append(child_node)
            
            i += 1
            
        return texts_to_translate, nodes_to_update

    def translate_markdown_content(self, md_content, translator):
        """
        执行翻译流程，返回翻译后的完整字符串
        """
        # --- 步骤 1: 全局保护公式 ---
        # 优化正则：$$ 支持跨行，但 $ 严禁跨行且内部必须有非空白字符
        # 防止因文档中散落的 $ 符号导致误匹配大段文字
        formula_pattern = re.compile(r'(\$\$.*?\$\$|\$[^\$\n]+?\$)', re.DOTALL)
        stored_formulas = []
        
        def hide_formula(match):
            placeholder = f"MATH_FIXED_{len(stored_formulas)}X"
            stored_formulas.append(match.group(0))
            return placeholder
        
        # 在解析前全量替换
        protected_md = formula_pattern.sub(hide_formula, md_content)
        
        # --- 步骤 2: 解析保护后的 Markdown ---
        tokens = self.md_parser.parse(protected_md)
        
        # --- 步骤 3: 提取可翻译内容 ---
        texts, nodes = self._extract_translatable_content(tokens)
        
        print(f"解析完成，提取到 {len(texts)} 个待翻译文本片段。")
        
        if not texts:
            print("未发现可翻译内容。正在尝试还原公式并返回...")
            # 即使没有文本，也要把占位符换回来
            final_content = self.renderer.render(tokens)
            for i, formula in enumerate(stored_formulas):
                final_content = final_content.replace(f"MATH_FIXED_{i}X", formula)
            return final_content
            
        # --- 步骤 4: 顺序翻译 ---
        # --- 步骤 4: 并发翻译 (优化版) ---
        from tqdm import tqdm
        from concurrent.futures import ThreadPoolExecutor, as_completed
        
        # 默认并发线程数
        MAX_WORKERS = 8
        print(f"开始翻译 (并发线程数: {MAX_WORKERS})...")
        
        translated_count = 0
        with ThreadPoolExecutor(max_workers=MAX_WORKERS) as executor:
            # 提交任务
            future_to_node = {
                executor.submit(translator.translate, text): (i, text, node) 
                for i, (text, node) in enumerate(zip(texts, nodes))
            }
            
            # 处理结果
            for future in tqdm(as_completed(future_to_node), total=len(texts), unit="chunk"):
                original_idx, text, node = future_to_node[future]
                try:
                    translated_text = future.result()
                    if translated_text:
                        node.content = translated_text
                        translated_count += 1
                except Exception as e:
                    print(f"Translation failed for chunk #{original_idx}: {e}")
        
        print(f"翻译完成 {translated_count}/{len(texts)}。正在重构 Markdown...")
        
        # --- 步骤 5: 重构 Markdown ---
        new_content = self.renderer.render(tokens)
        
        # --- 步骤 6: 全局还原公式 ---
        # --- 步骤 6: 全局还原公式 (优化版) ---
        # 使用单次扫描替换所有占位符，复杂度从 O(N*M) 降低到 O(M)
        
        def restore_callback(match):
            try:
                # 提取数字部分并去除可能存在的空格
                idx_str = re.sub(r'\s+', '', match.group(1))
                idx = int(idx_str)
                if 0 <= idx < len(stored_formulas):
                    return stored_formulas[idx]
                return match.group(0) # 索引越界，保留原样
            except Exception:
                return match.group(0)

        if stored_formulas:
            print(f"正在还原 {len(stored_formulas)} 个公式...")
            # 匹配 MATH_FIXED_nX，允许字符间有空白 (兼容性处理)
            # 正则解释: M \s* A \s* ... \s* _ \s* (数字及空格) \s* X
            restore_pattern = re.compile(
                r'M\s*A\s*T\s*H\s*_\s*F\s*I\s*X\s*E\s*D\s*_\s*(\d+(?:\s*\d+)*)\s*X', 
                re.IGNORECASE
            )
            # 使用 lambda 包装 callback 并不是必须的，直接传 callback 即可
            # 但为了防止 callback 返回的字符串包含反斜杠被 sub 误处理（standard re behavior），
            # 实际上 re.sub 的 replacement如果是函数，返回的字符串会被如实对待，不会解析 backreferences。
            # 参考: https://docs.python.org/3/library/re.html#re.sub
            # "If repl is a function... The returned string is processed." -> Wait, "processed"? 
            # documentation says: "Backreferences... are processed". 
            # 其实 Python re.sub 如果 repl 是 function，返回的 string 里的 backslashes *are* processed (unlike some other engines).
            # 所以我们需要对 callback 的返回值进行 escape 吗？
            # 官方文档： "If repl is a function... The returned string is processed."
            # 实测：re.sub(pattern, lambda m: "\\", text) -> returns "\" (single backslash). It seems OK in Python 3.
            # 但之前的代码特地用了 lambda _: formula，可能是为了保险。
            # 我们还是手动处理一下 callback 吧。
            
            # 修正：其实这里只要 return 原始 formula 就行。之前的 lambda 是 pattern.sub(lambda _: formula, new_content)。 
            # 之前的 logic 是循环 replace，每次 formula 都是固定的 string。
            # 现在的 logic 是 callback 动态返回 formula。
            new_content = restore_pattern.sub(restore_callback, new_content)
        
        return new_content


class SimpleMarkdownRenderer:
    """
    Reconstruct markdown from tokens. 
    Improved to handle links, nested lists, blockquotes, table alignment, and HTML.
    """
    def render(self, tokens):
        output = []
        link_stack = [] # Stack to store hrefs for closing tags
        
        # State tracking
        list_stack = []     # 'bullet' or 'ordered'
        list_indexes = []   # Counters for ordered lists
        blockquote_depth = 0
        
        in_table = False
        table_alignments = []
        table_row_buffer = []  # Buffer for current table row
        in_thead = False

        # Helper to get current indentation (parents)
        def get_indent():
            indent = ""
            if list_stack:
                # 2 spaces per *nested* list level
                indent += "  " * (len(list_stack) - 1)
            return indent

        # Helper to get blockquote prefix
        def get_bq_prefix():
            return "> " * blockquote_depth

        for i, token in enumerate(tokens):
            
            # --- Block Structure ---
            
            if token.type == 'blockquote_open':
                blockquote_depth += 1
                # Check previous token to decide if we need a newline before starting blockquote sequence
                if i > 0 and tokens[i-1].type not in ['blockquote_open']:
                     output.append('\n')
                output.append('> ')

            elif token.type == 'blockquote_close':
                blockquote_depth -= 1
                if blockquote_depth == 0:
                    output.append('\n')

            elif token.type == 'bullet_list_open':
                list_stack.append('bullet')
                list_indexes.append(0)
                if len(list_stack) == 1:
                     output.append('\n')

            elif token.type == 'ordered_list_open':
                list_stack.append('ordered')
                start = 1
                if token.attrs and 'start' in token.attrs:
                     try: start = int(token.attrs['start'])
                     except: pass
                list_indexes.append(start)
                if len(list_stack) == 1:
                     output.append('\n')

            elif token.type == 'bullet_list_close' or token.type == 'ordered_list_close':
                list_stack.pop()
                list_indexes.pop()
                if not list_stack:
                    output.append('\n')

            elif token.type == 'list_item_open':
                # Determine prefix
                prefix = get_bq_prefix() + get_indent()
                
                if list_stack and list_stack[-1] == 'ordered':
                    idx = list_indexes[-1]
                    marker = f"{idx}. "
                    list_indexes[-1] += 1
                else:
                    marker = "- "
                
                # If inside another list item, we might need a newline
                # But standard markdown list items usually start on new lines.
                output.append('\n' + prefix + marker)

            elif token.type == 'list_item_close':
                pass 

            # --- Headings ---
            elif token.type == 'heading_open':
                output.append('\n' + get_bq_prefix() + '#' * int(token.tag[1:]) + ' ')
            
            elif token.type == 'heading_close':
                output.append('\n')

            # --- Paragraphs ---
            elif token.type == 'paragraph_open':
                # Check if we need a newline. If inside list item which just opened, no newline needed data-wise,
                # but visually we handled it in list_item_open.
                prev_token = tokens[i-1] if i > 0 else None
                
                needs_newline = True
                if prev_token:
                    if prev_token.type == 'list_item_open':
                        needs_newline = False
                    elif prev_token.type == 'blockquote_open':
                        needs_newline = False # Blockquote start handled
                
                if needs_newline:
                    # indented text for paragraph inside list
                    # If it's a paragraph inside a list item (not the first one), it needs full indentation
                    # (parent indent + marker width approx). 
                    # For simplicity, we just use same indent + 2 spaces or so.
                    # But for now, let's just use get_indent() which marks hierarchy.
                    
                    # Special case: Multiline list items not fully supported by this simple renderer logic yet
                    # logic for simplicity: Just print newline and prefix
                    output.append('\n' + get_bq_prefix() + get_indent())

            elif token.type == 'paragraph_close':
                output.append('\n')

            # --- Code Blocks ---
            elif token.type == 'fence':
                 info = token.info if token.info else ''
                 prefix = '\n' + get_bq_prefix() + get_indent()
                 lines = token.content.split('\n')
                 if lines and lines[-1] == '': lines.pop()
                 
                 output.append(f"{prefix}```{info}")
                 for line in lines:
                     output.append(f"{prefix}{line}")
                 output.append(f"{prefix}```\n")

            elif token.type == 'code_block':
                 lines = token.content.split('\n')
                 if lines and lines[-1] == '': lines.pop()
                 prefix = '\n' + get_bq_prefix() + get_indent() + "    "
                 for line in lines:
                     output.append(prefix + line)
                 output.append('\n')

            # --- HTML Blocks ---
            elif token.type == 'html_block':
                output.append('\n' + get_bq_prefix() + token.content.strip())

            elif token.type == 'hr':
                output.append('\n---\n')

            # --- Tables ---
            elif token.type == 'table_open':
                in_table = True
                table_alignments = []
                output.append('\n' + get_bq_prefix())

            elif token.type == 'table_close':
                in_table = False
                output.append('\n')

            elif token.type == 'thead_open':
                in_thead = True

            elif token.type == 'thead_close':
                in_thead = False
                # Render separator
                sep_parts = []
                for align in table_alignments:
                    if align == 'center':
                        sep_parts.append(':---:')
                    elif align == 'right':
                        sep_parts.append('---:')
                    else:
                        sep_parts.append('---')
                
                # Check if we have columns
                if sep_parts:
                    output.append('| ' + ' | '.join(sep_parts) + ' |\n' + get_bq_prefix())

            elif token.type == 'tr_open':
                table_row_buffer = []

            elif token.type == 'tr_close':
                output.append('| ' + ' | '.join(table_row_buffer) + ' |\n' + get_bq_prefix())

            elif token.type == 'th_open' or token.type == 'td_open':
                if token.type == 'th_open':
                    # Extract alignment
                    style = token.attrs.get('style', '') if token.attrs else ''
                    align = 'left'
                    if 'text-align:center' in style: align = 'center'
                    elif 'text-align:right' in style: align = 'right'
                    table_alignments.append(align)

            elif token.type == 'th_close' or token.type == 'td_close':
                pass # Handled in loop or inline processing

            # --- Inline ---
            elif token.type == 'inline':
                s_output = []
                if token.children:
                    for child in token.children:
                        if child.type == 'text':
                            s_output.append(child.content)
                        elif child.type == 'code_inline':
                            s_output.append(f"`{child.content}`")
                        elif child.type == 'strong_open':
                            s_output.append('**')
                        elif child.type == 'strong_close':
                            s_output.append('**')
                        elif child.type == 'em_open':
                            s_output.append('*')
                        elif child.type == 'em_close':
                            s_output.append('*')
                        elif child.type == 'image':
                            src = child.attrs.get('src', '') if isinstance(child.attrs, dict) else dict(child.attrs).get('src', '')
                            alt = child.content
                            s_output.append(f"![{alt}]({src})")
                        elif child.type == 'link_open':
                             s_output.append('[')
                             link_stack.append(child.attrs.get('href', '') if isinstance(child.attrs, dict) else dict(child.attrs).get('href', ''))
                        elif child.type == 'link_close':
                             url = link_stack.pop() if link_stack else ''
                             s_output.append(f']({url})')
                        elif child.type == 'softbreak':
                            s_output.append(' ')
                        elif child.type == 'hardbreak':
                            s_output.append('  \n')
                        elif child.type == 'html_inline':
                            s_output.append(child.content)
                        elif child.type == 's_open':
                            s_output.append('~~')
                        elif child.type == 's_close':
                            s_output.append('~~')
                else:
                    s_output.append(token.content)
                
                content = "".join(s_output)
                if in_table:
                    content = content.replace('\n', '<br>').replace('|', '\|')
                    table_row_buffer.append(content)
                else:
                    output.append(content)

        return "".join(output).strip()

